import { multiplyMoney, sameMoney, sumMoney } from "../../core/money.ts";
import { isObject } from "../../core/request-body.ts";
import { qboDate } from "./dates.ts";
import { type QboFault, qboErrors } from "./errors.ts";
import type { QboInvoice, QboInvoiceLine, QboRef, QboSalesItemLine, QboState, QboSubTotalLine, WRITABLE_INVOICE_FIELDS } from "./types.ts";
import { asSent, checkLengths, readAmount, readOptionalNumber, readTextFields, refId } from "./values.ts";

/**
 * How QuickBooks builds an invoice from a request: references, lines, totals, numbers, and dates.
 * Shared by create, sparse update, and full update.
 * Reference: https://developer.intuit.com/app/developer/qbo/docs/api/accounting/all-entities/invoice
 */

export type InvoiceFields = Partial<Pick<QboInvoice, (typeof WRITABLE_INVOICE_FIELDS)[number]>>;

/** What the caller controls, checked and completed. The caller adds Id, SyncToken, MetaData, and links. */
export type InvoiceDraft = Omit<QboInvoice, "Id" | "SyncToken" | "MetaData" | "LinkedTxn" | "Balance">;

const MAX_LENGTHS = { DocNumber: 21, PrivateNote: 4000 }; // each field's "max character" in the Invoice reference
const FIRST_DOC_NUMBER = 1001; // the twin's company starts invoice numbers here

export function draftInvoice(
  state: QboState,
  fields: InvoiceFields,
  options: { today: string; now: string; existingLines?: QboInvoiceLine[]; existingCustomerId?: string; isCreate: boolean },
): InvoiceDraft | QboFault {
  const { now } = options;
  const badText = readTextFields(fields, ["DocNumber", "PrivateNote"], now) ?? checkLengths(fields, MAX_LENGTHS, now);
  if (badText) return badText;

  // "An invoice must have CustomerRef populated."
  if (!fields.CustomerRef?.value) return qboErrors.missingField("CustomerRef", now);
  const customerId = refId(fields.CustomerRef.value);
  const customer = customerId === undefined ? undefined : state.customers.get(customerId);
  if (!customer) return qboErrors.invalidReference("CustomerRef", `Customer ${asSent(fields.CustomerRef.value)}`, now);
  // An inactive customer gets no new invoices, but the invoices it already has can still be updated.
  if (!customer.Active && customer.Id !== options.existingCustomerId) {
    return qboErrors.invalidReference("CustomerRef", `Customer ${customer.Id}, which is inactive`, now);
  }

  const lines = salesLines(state, fields.Line, options.existingLines ?? [], now);
  if ("Fault" in lines) return lines;

  // "If Preferences:CustomTxnNumber is false, resulting DocNumber is system generated by incrementing the
  // last number by 1." A DocNumber the caller sends is kept. Duplicates are accepted (see FIDELITY.md).
  const DocNumber = fields.DocNumber ?? (options.isCreate ? nextDocNumber(state) : undefined);

  // "If the date is not supplied, the current date on the server is used." DueDate is TxnDate plus the
  // sales terms' days; the twin has no sales terms, so that is TxnDate itself.
  const TxnDate = fields.TxnDate === undefined ? options.today : qboDate(fields.TxnDate);
  if (!TxnDate) return qboErrors.invalidDate("TxnDate", asSent(fields.TxnDate), now);
  const DueDate = fields.DueDate === undefined ? TxnDate : qboDate(fields.DueDate);
  if (!DueDate) return qboErrors.invalidDate("DueDate", asSent(fields.DueDate), now);

  const subtotal = sumMoney(lines.map((line) => line.Amount));
  const subtotalLine: QboSubTotalLine = { Amount: subtotal, DetailType: "SubTotalLineDetail", SubTotalLineDetail: {} };

  return {
    ...fields,
    ...(DocNumber !== undefined && { DocNumber }),
    TxnDate,
    DueDate,
    CustomerRef: { value: customer.Id, name: customer.DisplayName },
    // "If ShipAddr, BillAddr, or both are not provided, the appropriate customer address ... is used."
    BillAddr: fields.BillAddr ?? customer.BillAddr,
    Line: [...lines, subtotalLine],
    TotalAmt: subtotal, // no sales tax in the twin, so the total is the subtotal
  };
}

/** The sales lines of a request, validated, with Ids and LineNums assigned. */
function salesLines(state: QboState, input: unknown, existing: QboInvoiceLine[], now: string): QboSalesItemLine[] | QboFault {
  if (input === undefined || input === null) return qboErrors.missingField("Line", now);
  // A Line that is there but isn't a list is malformed, not missing: 2010, as a payment's Line gets.
  if (!Array.isArray(input))
    return qboErrors.invalidProperty("Line", 'Line must be a list of lines, like [{"DetailType": "SalesItemLineDetail", ...}].', now);
  if (!input.every(isObject))
    return qboErrors.invalidProperty("Line", 'Each line must be an object, like {"DetailType": "SalesItemLineDetail", ...}.', now);

  // Clients often send back the SubTotalLine they read. QuickBooks recomputes it, so it is ignored here.
  const requested = (input as LineInput[]).filter((line) => line?.DetailType !== "SubTotalLineDetail");
  if (requested.length === 0) return qboErrors.missingField("Line", now);

  const keptIds = new Set(existing.flatMap((line) => ("Id" in line ? [line.Id] : [])));
  let nextLineId = Math.max(0, ...[...keptIds].map(Number)) + 1;
  const givenIds = new Set<string>(); // Ids used so far in this request
  const lines: QboSalesItemLine[] = [];

  for (const [index, line] of requested.entries()) {
    if (line.DetailType !== "SalesItemLineDetail") {
      const sent = line.DetailType === undefined ? "(missing)" : asSent(line.DetailType);
      return qboErrors.unsupportedOperation(
        `The twin models SalesItemLineDetail lines only. Line ${index + 1} has DetailType ${sent}.`,
        now,
      );
    }
    const Amount = readAmount(line.Amount, "Line.Amount", now);
    if (typeof Amount !== "number") return Amount;

    const detail = line.SalesItemLineDetail ?? {};
    if (!detail.ItemRef?.value) return qboErrors.missingField("Line.SalesItemLineDetail.ItemRef", now);
    const itemId = refId(detail.ItemRef.value);
    const item = itemId === undefined ? undefined : state.items.get(itemId);
    if (!item?.Active) return qboErrors.invalidReference("Line.SalesItemLineDetail.ItemRef", `Item ${asSent(detail.ItemRef.value)}`, now);

    const Qty = readOptionalNumber(detail.Qty, "Line.SalesItemLineDetail.Qty", "quantity", now);
    if (typeof Qty === "object") return Qty;
    const UnitPrice = readOptionalNumber(detail.UnitPrice, "Line.SalesItemLineDetail.UnitPrice", "price", now);
    if (typeof UnitPrice === "object") return UnitPrice;
    if (Qty !== undefined && UnitPrice !== undefined && !sameMoney(multiplyMoney(Qty, UnitPrice), Amount)) {
      return qboErrors.amountMismatch(Amount, now);
    }

    // An update keeps the Id of a line it sends back; new lines get new Ids. A second copy of a line (a client
    // that cloned a line it read, Id and all) is a new line, so two lines never share an Id.
    const sentId = refId(line.Id);
    if (line.Id !== undefined && sentId === undefined) {
      return qboErrors.invalidProperty(
        "Line.Id",
        `Line ${index + 1} has Id ${asSent(line.Id)}. Send the Id you read, or none for a new line.`,
        now,
      );
    }
    const Id = sentId !== undefined && keptIds.has(sentId) && !givenIds.has(sentId) ? sentId : String(nextLineId++);
    givenIds.add(Id);
    lines.push({
      Id,
      LineNum: index + 1,
      ...(line.Description !== undefined && { Description: line.Description }),
      Amount,
      DetailType: "SalesItemLineDetail",
      SalesItemLineDetail: {
        ItemRef: { value: item.Id, name: item.Name },
        ...(Qty !== undefined && { Qty }),
        ...(UnitPrice !== undefined && { UnitPrice }),
        ...(detail.ServiceDate !== undefined && { ServiceDate: detail.ServiceDate }),
      },
    });
  }
  return lines;
}

interface LineInput {
  Id?: unknown; // the line's Id as text or a number, checked by refId
  Description?: string;
  Amount?: unknown; // a number or a numeric string, checked by readAmount
  DetailType?: unknown;
  SalesItemLineDetail?: { ItemRef?: QboRef; Qty?: unknown; UnitPrice?: unknown; ServiceDate?: string };
}

/**
 * The last ordinary invoice number plus one, counted with BigInt so a long number goes on exactly. A DocNumber
 * like "JB-77" is skipped, and so is one whose next number wouldn't fit DocNumber's 21 characters.
 */
function nextDocNumber(state: QboState): string {
  let last = BigInt(FIRST_DOC_NUMBER - 1);
  for (const { DocNumber = "" } of state.invoices.values()) {
    if (!/^\d+$/.test(DocNumber)) continue;
    const number = BigInt(DocNumber);
    if (number > last && String(number + 1n).length <= MAX_LENGTHS.DocNumber) last = number;
  }
  return String(last + 1n);
}
